  "Mulligan em {m} de {t} jogos: mãos iniciais fracas — mais terrenos ou mais cartas de custo 1–2.": "{t} 局中有 {m} 局调度：起手太弱——增加地或 1–2 费的牌。",
  "As derrotas chegam cedo (turno ~{l}) e só começas a causar dano no turno ~{f}: precisas de interação barata (remoção de custo 1–2) ou de bloqueadores cedo.": "落败来得很早（约第 {l} 回合），而你要到约第 {f} 回合才开始造成伤害：你需要便宜的互动（1–2 费移除）或早期阻挡者。",
  "As derrotas chegam cedo (turno ~{l}): precisas de interação barata (remoção de custo 1–2) ou de bloqueadores cedo.": "落败来得很早（约第 {l} 回合）：你需要便宜的互动（1–2 费移除）或早期阻挡者。",
  "ver remoção": "查看移除",
  "Mais dano sofrido de: {l}.": "受到伤害最多的来源：{l}。",
  "Respostas possíveis: {r}.": "可用的解答：{r}。",
  "Reforça a remoção para estas ameaças.": "针对这些威胁加强移除。",
  "juntar ao sideboard": "加入备牌",
  "juntar": "加入",
  "Melhorias sugeridas pelos testes": "测试建议的改进",
  "Volta a correr os testes depois de aplicar para confirmar se melhorou.": "应用后请重新运行测试，确认是否有改善。",
  "Eliminação simples": "单淘汰",
  "Quem perde sai. Se o número de decks não for 4, 8 ou 16, os melhores seeds passam a 1.ª ronda sem jogar (isentos). Pode haver jogo de 3.º lugar entre os vencidos das meias-finais.": "输者出局。若套牌数不是 4、8 或 16，排名靠前的种子直接轮空第 1 轮。半决赛的两名败者之间可以进行季军赛。",
  "Dupla eliminação": "双败淘汰",
  "Só sai quem perde duas vezes: a 1.ª derrota manda para a chave dos vencidos. O vencedor dessa chave defronta o invicto na grande final; se a ganhar, joga-se a 2.ª final.": "输两次才出局：第 1 次落败进入败者组。败者组冠军在总决赛中对阵不败者；若败者组冠军获胜，则再打第 2 场决赛。",
  "Suíço": "瑞士轮",
  "Todos jogam todas as rondas, sempre contra quem tem os mesmos pontos e sem repetir adversários (vitória 3, empate 1; quem fica isento conta como vitória). Desempate: % de vitórias dos adversários (OMW%) e % de jogos ganhos (GW%).": "所有人参加每一轮，总是与同分者配对且不重复对手（胜 3 分，平 1 分；轮空算胜）。同分排名依据：对手比赛胜率（OMW%）和局胜率（GW%）。",
  "Liga (todos contra todos)": "联赛（循环赛）",
  "Cada deck joga uma vez contra cada um dos outros; vitória 3, empate 1. O mais justo e o mais longo.": "每副套牌与其他每副套牌各打一次；胜 3 分，平 1 分。最公平，也最耗时。",
  "Mesas (multijogador)": "牌桌（多人）",
  "Para Commander e jogos a 3–4: mesas de todos contra todos, um jogo por mesa; pontos pelo lugar (1.º 3, 2.º 2, 3.º 1, 4.º 0). Em cada ronda as mesas refazem-se pelos pontos.": "用于指挥官和 3–4 人对局：混战牌桌，每桌一局；按名次计分（第 1 名 3 分、第 2 名 2 分、第 3 名 1 分、第 4 名 0 分）。每轮按积分重新分桌。",
