  "Bo3 com sideboard inteligente entre jogos, como no Laboratório (decks com sideboard, em formatos que o têm), e aprende com as trocas que já perderam.": "Bo3 局间智能换备牌，与实验室相同（适用于有备牌的套牌及支持备牌的赛制），并会从曾导致落败的换牌中学习。",
  "Empates na eliminação repetem o jogo (até 2 vezes); depois passa o melhor seed. Jogos em que o Forge falha repetem-se.": "淘汰赛中平局会重赛（最多 2 次）；之后由种子排名较高者晋级。Forge 出错的对局会重打。",
