  "E o TappedOut, Moxfield e o meta?": "TappedOut、Moxfield 和环境套牌呢？",
  "pesquisa no próprio site (tappedout.net/mtg-decks/search/) e, na página de resultados, carrega no favorito «Grimório: levar decks» (em «Importar decks de um perfil»): traz todos os decks da página com as imagens, para escolheres.": "在该网站上搜索（tappedout.net/mtg-decks/search/），然后在结果页点击书签「Grimório：抓取套牌」（见「从个人主页导入套牌」）：它会带回该页所有套牌及其图片，供你挑选。",
  "o site bloqueia pesquisas do servidor; cola os links dos decks em «Importar decks de um perfil».": "该网站拦截来自服务器的搜索；请把套牌链接粘贴到「从个人主页导入套牌」。",
  "Meta de torneios": "赛事环境",
  "«Decks do meta», mais abaixo (MTGTop8 e EDHREC), com «Guardar nos meus decks».": "见下方「环境套牌」（MTGTop8 和 EDHREC），使用「保存到我的套牌」。",
  "Não encontrei decks nesta página.": "此页面未找到套牌。",
  "A ler o perfil…": "正在读取个人主页…",
  "O TappedOut não deixa o servidor ler perfis. Usa o favorito abaixo na tua página de perfil, ou cola os links dos decks.": "TappedOut 不允许服务器读取个人主页。请在你的个人主页上使用下方的书签，或粘贴套牌链接。",
