  "cola o link do perfil": "粘贴个人主页链接",
  "o-teu-nome": "你的用户名",
  "e escolhe os decks. Vem também a capa de cada deck (a imagem que puseste no Archidekt, ou a carta em destaque).": "然后选择套牌。每副套牌的封面也会一并导入（你在 Archidekt 上设置的图片，或展示牌）。",
  "o site não deixa o servidor entrar, por isso usa o favorito abaixo, que corre no teu browser. Na": "该网站不允许服务器访问，所以请使用下方的书签，它在你的浏览器中运行。在你的",
  "página de perfil": "个人主页",
  "traz todos os decks com a imagem de cada um; na": "上，它会带回所有套牌及各自的图片；在",
  "página de um deck": "单个套牌页面",
  "traz só esse, com a imagem. Se o deck já existir aqui com o mesmo nome, só lhe atualiza a capa e as artes das cartas (as imagens que escolheste no TappedOut, alteradas incluídas).": "上，只带回该套牌及其图片。如果这里已有同名套牌，只会更新它的封面和卡图（即你在 TappedOut 上选择的图片，包括改绘卡图）。",
  "cola os links dos decks, um por linha (o perfil não é público pela API). Vem a arte da carta em destaque.": "粘贴套牌链接，每行一个（个人主页无法通过 API 公开读取）。展示牌的卡图会一并导入。",
  "cola os links, um por linha. Estes sites não têm capa; escolhe-a depois na Biblioteca (🖼).": "粘贴链接，每行一个。这些网站没有封面；之后在牌组库中选择（🖼）。",
  "Qualquer deck: na Biblioteca, 🖼 deixa escolher uma carta do deck, colar o link de uma imagem ou carregar uma imagem tua.": "任何套牌：在牌组库中，🖼 可以选择套牌中的一张牌、粘贴图片链接或上传你自己的图片。",
  "TappedOut: favorito para levar os decks (e as imagens)": "TappedOut：用书签抓取套牌（及图片）",
  "Arrasta este link para a barra de favoritos:": "将此链接拖到书签栏：",
  "Grimório: levar decks": "Grimório：抓取套牌",
  "Depois abre a tua página de decks no TappedOut": "然后打开你在 TappedOut 上的套牌页面",
  "ou a página de um deck e carrega no favorito: o Grimório abre com esses decks para escolheres. No telemóvel ou tablet: cria um favorito qualquer, edita-o e cola este endereço no lugar do link (copia-o com toque longo).": "或某个套牌的页面，然后点击书签：Grimório 会打开并列出这些套牌供你选择。在手机或平板上：随便创建一个书签，编辑它，把这个地址粘贴到链接处（长按即可复制）。",
