  "o Grimório dá um nome se ficar vazio": "留空则由 Grimório 命名",
  "Como queres começar?": "你想如何开始？",
  "Traz um deck que já tens (link do Moxfield, Archidekt, TappedOut, MTGGoldfish, Deckstats, MTGTop8, Scryfall, ou a lista colada). Depois de importar abre-se o diagnóstico «Melhorias prioritárias», com cortes, trocas, base de mana e o assistente IA para o melhorar.": "带来你已有的套牌（Moxfield、Archidekt、TappedOut、MTGGoldfish、Deckstats、MTGTop8、Scryfall 的链接，或粘贴牌表）。导入后会打开「优先改进」诊断，包含删减、替换、法术力基础以及帮你改进的 AI 助手。",
  "Importar deck": "导入套牌",
  "Começas com o deck vazio e vais metendo as cartas tu. Ao lado da pesquisa, o painel «Sugestões para este deck» acompanha-te em tempo real: a cada carta que entra, recalcula o que combina, o que falta ao formato e a base de mana, sempre com o porquê.": "从空套牌开始，由你自己逐张加入。搜索旁边的「本套牌建议」面板会实时跟进：每加入一张牌，它都会重新计算哪些牌搭配、赛制还缺什么以及法术力基础，并始终说明理由。",
  "Começa pelo comandante (♛ numa carta lendária).": "从指挥官开始（在传奇牌上点 ♛）。",
  "Começar a construir": "开始构筑",
  "A IA é um extra opcional e está desligada. Escolhe um fornecedor (o Gemini tem plano gratuito):": "AI 是可选附加功能，目前已关闭。选择一个提供商（Gemini 有免费方案）：",
  "Ex.: elfos verde-preto, barato, que ganhe a encher a mesa de fichas e sacrifica-las": "例如：黑绿妖精，低预算，靠铺满衍生物再牺牲它们取胜",
  "Ex.: aggro vermelho com muitos feitiços baratos e prowess": "例如：红色快攻，大量低费咒语和勇武",
