  "Produz as cores do deck": "产出套牌的颜色",
  "Terrenos básicos": "基本地",
  "Equilibra as fontes: {s}": "平衡法术力来源：{s}",
  "O perfil de referência do Forge: equilibrado entre atacar e defender.": "Forge 的基准档案：攻守平衡。",
  "Evita atacar para bloqueios certos e raramente ataca só para trocar criaturas (≈10%).": "避免攻进必然被阻挡的局面，很少只为换掉生物而攻击（≈10%）。",
  "Guarda truques de combate até haver bloqueios (≈65% das vezes).": "留着战斗戏法直到宣告阻挡（≈65% 的情况）。",
  "Contraria sempre feitiços de custo 3 ou mais, muitas vezes os de custo 2 (≈75%) e às vezes os de custo 1 (≈30%).": "总是反击法术力值 3 以上的咒语，经常反击 2 费的（≈75%），有时反击 1 费的（≈30%）。",
  "Encadeia feitiços de dano para matar (≈90%).": "连续施放直伤咒语来斩杀（≈90%）。",
  "Faz mulligan com mãos fracas (limiar normal).": "起手较弱时调度（正常阈值）。",
  "Cautelosa": "谨慎",
  "Defensiva: troca menos criaturas, gasta menos recursos e protege-se.": "防守型：换掉的生物更少，消耗的资源更少，注重自保。",
  "Quase nunca ataca para trocar criaturas quando o adversário tem mana aberta (≈10% em vez de 30%).": "对手有未横置的法术力时几乎从不为换生物而攻击（≈10%，而非 30%）。",
  "Só troca criaturas se não ficar com menos no campo; não usa ataques arriscados.": "只在战场上的生物不会变少时才交换；不做冒险的攻击。",
  "Contraria menos: de custo 1 só dano, remoção e outros contra-feitiços; metade dos de custo 2.": "反击得更少：1 费的只反击直伤、移除和其他反击咒语；2 费的反击一半。",
  "Raramente encadeia dois feitiços de dano (≈25% em vez de 90%).": "很少连续施放两个直伤咒语（≈25%，而非 90%）。",
  "Sente-se em perigo mais cedo e protege mais os planeswalkers (troca para os salvar ≈90%).": "更早感到威胁，更加保护鹏洛客（为救它们而交换 ≈90%）。",
  "Paga energia só para se defender; scry/surveil mais conservadores.": "只为防守而支付能量；占卜/刺探更保守。",
  "Imprudente": "鲁莽",
  "Agressiva: ataca sempre que pode, troca criaturas sem medo e arrisca mãos curtas.": "进攻型：能攻击就攻击，毫不犹豫地交换生物，敢于保留少牌的起手。",
  "Joga em modo agressivo: ataca para trocar criaturas quase sempre (≈90%), mesmo com o adversário de mana aberta.": "以进攻模式游戏：几乎总是为交换生物而攻击（≈90%），即便对手有未横置的法术力。",
  "Ataca mesmo quando fica sem mana para responder.": "即使攻击后没有法术力回应也照样攻击。",
  "Aceita mãos piores (limiar de mulligan mais baixo).": "接受更差的起手（调度阈值更低）。",
  "Contraria muito mais: quase tudo de custo 1 (≈80%) e tudo de custo 2 ou mais.": "反击得多得多：几乎所有 1 费的（≈80%），以及所有法术力值 2 以上的。",
  "Gasta feitiços de dano X mais cedo, com menos dano acumulado.": "更早打出 X 直伤咒语，累积的伤害更少。",
  "Lança mais cartas com flash cedo e move equipamentos para as melhores criaturas.": "更早施放有闪现的牌，并把武具移到最好的生物上。",
  "Experimental": "实验性",
  "Perfil de testes do Forge: mais oportunista e arriscado em várias decisões.": "Forge 的测试档案：在许多决策上更投机、更冒险。",
  "Sente-se em perigo mais tarde e aceita mais risco antes de defender.": "更晚才感到威胁，防守前愿意承受更多风险。",
  "Encadeia quase sempre dois feitiços de dano para matar (≈90%).": "几乎总是连续施放两个直伤咒语来斩杀（≈90%）。",
  "Usa quase sempre habilidades que criam fichas (≈90%) e responde mais vezes à pilha com flash.": "几乎总是使用产生衍生物的异能（≈90%），并更常在堆叠上用闪现回应。",
  "Move equipamentos sempre para a melhor criatura e reaproveita planeswalkers com blink.": "总是把武具移到最好的生物上，并用闪烁重置鹏洛客。",
  "Troca criaturas para salvar planeswalkers mesmo perdendo (≈40%).": "即使吃亏也会交换生物来救鹏洛客（≈40%）。",
  "Faz sideboard por vezes mesmo depois de ganhar (≈25%).": "有时即使赢了也会换备牌（≈25%）。",
  "Forte (verifica jogadas)": "强（验证出牌）",
  "O perfil Normal com uma verificação do Forge: antes de cada jogada simula-a e põe de lado as que deixam o jogo pior.": "普通档案加上 Forge 的验证：每次出牌前先模拟，排除让局面变差的出牌。",
  "Decide como a Normal (as mesmas regras por carta: contra-feitiços, reanimação, combate) e veta as jogadas que perdem valor.": "决策方式与普通相同（每张牌的规则一样：反击咒语、复活、战斗），并否决会损失价值的出牌。",
  "Respostas na pilha (contrariar, truques) seguem a Normal: a simulação do Forge não vê a pilha.": "堆叠上的回应（反击、戏法）沿用普通：Forge 的模拟看不到堆叠。",
  "Não é mais lenta do que a Normal na prática; o relógio do Forge estica para o triplo por segurança.": "实际上并不比普通慢；为保险起见 Forge 的计时延长到三倍。",
  "A pesquisa completa do Forge ficou de fora: não dava valor ao cemitério nem às respostas e esgotava a memória.": "未采用 Forge 的完整搜索：它不重视坟墓场和应对手段，而且会耗尽内存。",
  "Aleatória": "随机",
  "Cada jogo sorteia um dos perfis acima: bom para testar contra estilos variados.": "每局从上面的档案中随机抽一个：适合测试对抗各种风格。",
  "Útil em séries longas para não afinar o deck contra um único estilo de jogo.": "在长系列对局中很有用，避免把套牌只针对一种打法调校。",
  "A dificuldade Forte, os jogos a 3–4 e o modo casual precisam do lançador do Grimório (build/forge/build.sh).": "强难度、3–4 人对局和休闲模式需要 Grimório 的启动器（build/forge/build.sh）。",
