  "A lista mudou {p} desde que ganhou os ratings (o máximo é 10%). Se gravares assim, as estrelas amarelas, azuis e vermelhas e o rating casual recomeçam do zero; os jogos antigos ficam na história. Os troféus seguem a regra deles.": "自获得评分以来，牌表已改动 {p}（上限 10%）。如果这样保存，黄、蓝、红星和休闲评分都将从零开始；旧对局仍保留在历史中。奖杯按其自身规则计算。",
