  "Encontrei neste computador:": "在此电脑上找到：",
  "Funciona com qualquer app grátis que mantenha uma pasta igual na nuvem: Google Drive para computador, OneDrive, Dropbox, Syncthing, Nextcloud ou iCloud Drive. Sem rede (num avião, p.ex.) continuas a usar tudo; a app leva as alterações quando a rede voltar.": "适用于任何能让文件夹与云端保持同步的免费应用：Google 云端硬盘电脑版、OneDrive、Dropbox、Syncthing、Nextcloud 或 iCloud 云盘。离线时（比如在飞机上）照常使用，联网后应用会自动上传更改。",
