  "Um link por linha. Cada um vai para a carta cujo nome aparece no endereço (como nos links do TappedOut); ou escreve «Nome da carta | link».": "每行一个链接。每个链接会关联到地址中出现其名称的卡牌（如 TappedOut 链接）；或写成“卡牌名 | 链接”。",
