  "A juntar {n} imagens…": "正在收集 {n} 张图片…",
  "Cada arte numa imagem de alta qualidade (PNG da Scryfall ou a tua), com o verso das cartas de duas faces e a lista dentro. Para enviar a uma gráfica (MakePlayingCards, loja local…).": "每种卡图一张高质量图片（Scryfall PNG 或你自己的），含双面牌背面和牌表，可发给印刷商（MakePlayingCards、本地店铺……）。",
  "Com a edição de cada carta (e uma linha por arte nas cópias divididas). Serve para o Moxfield, Archidekt, MPCFill, mtgprint e afins. As imagens próprias não passam por uma lista: usa o ZIP ou a folha.": "包含每张牌的版本（分配多种卡图的副本每种卡图一行）。适用于 Moxfield、Archidekt、MPCFill、mtgprint 等。自定义图片无法放进牌表：请用 ZIP 或打印页。",
