  "Tamanho real (63×88 mm), 9 por página, com linhas de corte. Abre numa janela nova pronta a imprimir ou a guardar em PDF.": "实际尺寸（63×88 毫米），每页 9 张，带裁切线。在新窗口打开，可直接打印或存为 PDF。",
  "Tirar do casual": "取消休闲",
  "Tirar {n} decks do modo casual?": "将 {n} 副套牌取消休闲模式？",
  "Tirar o deck do modo casual?": "将套牌取消休闲模式？",
  "Um deck casual pode ter cartas proibidas, banidas ou de fora do formato. Passa a jogar só em modo casual (Laboratório, torneios e Arena casuais) e só conta para o rating casual; deixa de entrar nos torneios e na Arena do formato.": "休闲套牌可以有禁牌、限制牌或赛制外的牌。只在休闲模式下对局（休闲实验室、锦标赛和竞技场），只计入休闲评分；不再参加该赛制的锦标赛和竞技场。",
  "Um ficheiro por cópia (em vez de «Island (x4)»)": "每张副本一个文件（而不是“Island (x4)”）",
  "Volta a seguir as regras do formato: entra nos torneios e na Arena do formato e conta para os ratings normais. Se tiver cartas que o formato não deixa, aparece como inválido até as trocares.": "恢复遵守赛制规则：可参加该赛制的锦标赛和竞技场，并计入普通评分。若含赛制不允许的牌，在换掉之前会显示为不合规。",
  "{n} imagem própria não veio (o site recusa descargas que não sejam do browser) e ficou a arte normal; a lista está no faltam.txt. Para as incluir, guarda-as no computador e junta-as em «Imagem própria › Uma pasta de imagens › Pasta do computador». A folha para imprimir já as mostra.|{n} imagens próprias não vieram (o site recusa descargas que não sejam do browser) e ficou a arte normal; a lista está no faltam.txt. Para as incluir, guarda-as no computador e junta-as em «Imagem própria › Uma pasta de imagens › Pasta do computador». A folha para imprimir já as mostra.": "{n} 张自定义图片无法下载（该网站拒绝非浏览器的下载），已改用普通卡图；清单在 faltam.txt。要包含它们，请保存到电脑，再在“自定义图片 › 图片文件夹 › 本机文件夹”中添加。打印页已能显示它们。|{n} 张自定义图片无法下载（该网站拒绝非浏览器的下载），已改用普通卡图；清单在 faltam.txt。要包含它们，请保存到电脑，再在“自定义图片 › 图片文件夹 › 本机文件夹”中添加。打印页已能显示它们。",
  "objetivo: média por jogo de quanto chega a ganhar (dano ÷ vida inicial, veneno ÷ 10, comandante ÷ 21, cartas tiradas da biblioteca ÷ biblioteca inicial; a melhor via conta, até 200%); 100% = 3★, 200% = 6★": "目标：每局平均离获胜有多近（伤害 ÷ 初始生命、中毒 ÷ 10、指挥官 ÷ 21、磨掉的牌 ÷ 初始牌库；取最佳途径，最多 200%）；100% = 3★，200% = 6★",
  "— quanto chega, em média, ao objetivo de ganhar (100% = 3★, 200% = 6★: acima de 3★ só quem passa do objetivo)": "— 平均离获胜目标有多近（100% = 3★，200% = 6★：超过 3★ 的只有超出目标的套牌）",
  "Clica em várias (até {m}): as cópias variam entre elas.": "可点选多张（最多 {m} 张）：副本会在其中轮换。",
