  "escolhe 2 a 4 para comparar": "选择 2 到 4 副进行比较",
  "Ganha por": "获胜方式",
  "Jogos": "对局",
  "quanto chega, em média, ao objetivo de ganhar": "平均离获胜目标有多近",
  "Rating": "评分",
  "Troféus": "奖杯",
  "Nos torneios não casuais entra sempre o meta (pelo menos 20%), para os ratings terem decks de referência.": "非休闲锦标赛总会加入环境套牌（至少 20%），让评分有参照套牌。",
  "Mistura": "混合比例",
  "Gauntlet (o meu deck contra todos)": "车轮战（我的套牌对所有人）",
  "O desafiante (o deck marcado com ☆ eu ou, sem ele, o 1.º da lista) joga uma partida contra cada um dos outros, pela ordem da lista. Só é campeão se ganhar pelo menos 75% das partidas; sem isso não há pódio.": "挑战者（标记为 ☆ 我 的套牌；没有标记时为列表第 1 个）按列表顺序与其他每个套牌各打一场比赛。只有赢下至少 75% 的比赛才算冠军，否则没有领奖台。",
  "Rei da colina": "山丘之王",
  "Dois decks jogam; quem ganha fica na colina e quem perde vai para o fim da fila, e o seguinte da fila desafia o rei. Num empate o rei fica. Ganha a série de vitórias mais longa (desempate: vitórias, depois menos derrotas).": "两个套牌对战；胜者留在山顶，败者排到队尾，队列中的下一个挑战山大王。平局时山大王留下。最长连胜者获胜（平分时：胜场，然后负场少者）。",
  "Grupos + eliminação": "小组赛 + 淘汰赛",
  "Grupos de 4 (ou de 3) em que todos jogam contra todos (vitória 3, empate 1). Os 2 primeiros de cada grupo passam a uma eliminação simples com jogo de 3.º lugar, em que os 1.ºs de grupo defrontam os 2.ºs de outros grupos.": "每组 4 个（或 3 个）套牌进行循环赛（胜 3 分，平 1 分）。每组前 2 名进入带季军赛的单败淘汰赛，小组第一对阵其他小组的第二。",
  "Equipas (2 ou 3 por equipa)": "团队赛（每队 2 或 3 个）",
  "Os decks formam equipas pela ordem da lista (1.º e 2.º = equipa 1…). As equipas jogam todas contra todas: o tabuleiro 1 de uma contra o tabuleiro 1 da outra, e assim por diante; ganha a equipa com mais tabuleiros ganhos (vitória 3, empate 1). Todos os decks da equipa sobem ao pódio.": "套牌按列表顺序组队（第 1 和第 2 个 = 第 1 队…）。各队进行循环赛：一队的 1 号台对另一队的 1 号台，依此类推；赢下更多台的队伍获胜（胜 3 分，平 1 分）。队伍中的所有套牌一起登上领奖台。",
  "N.º de partidas": "比赛场数",
  "Decks por equipa": "每队套牌数",
  "Equipa {e} · tabuleiro {b}": "第 {e} 队 · {b} 号台",
  "⚔ desafiante": "⚔ 挑战者",
