  "Cada torneio joga até {q} ao mesmo tempo, começando pelo {o}; os lugares que sobram vão para quem ainda tiver partidas.": "每个锦标赛最多同时进行 {q} 局，从{o}开始；剩余位置给仍有对局的锦标赛。",
