  "tira também vida": "同时扣生命",
  "Conta para as estrelas amarelas e dá troféus normais (ouro, prata e bronze).": "计入黄星，并颁发普通奖杯（金、银、铜）。",
  "Menos de 20% de decks do meta: conta só para as estrelas azuis e vermelhas e os troféus saem azuis.": "环境套牌少于 20%：只计入蓝星和红星，奖杯为蓝色。",
  "não ranked": "非排位",
  "Não ranked: {m} de {n} decks do meta (precisa de {k}). Conta só para as estrelas azuis e vermelhas e os troféus saem azuis.": "非排位：{n} 副中有 {m} 副环境套牌（需要 {k} 副）。只计入蓝星和红星，奖杯为蓝色。",
  "Nos torneios casuais os troféus saem azuis e as estrelas amarelas não mexem.": "休闲锦标赛的奖杯为蓝色，黄星不变。",
  "Ranked": "排位",
  "As estrelas (amarelas, azuis, vermelhas e casuais) dos teus decks voltam ao início. Os jogos antigos ficam no histórico e continuam a contar para os adversários.": "你的套牌的星级（黄、蓝、红和休闲）从头开始。旧对局保留在历史中，并继续计入对手。",
  "Continuar": "继续",
  "Os troféus de agora deixam de contar (Biblioteca, hall da fama e galeria). Os torneios ficam no registo e os próximos voltam a dar troféus.": "现有奖杯不再计入（套牌库、名人堂和陈列）。锦标赛保留在记录中，之后的锦标赛会重新颁发奖杯。",
  "Para começar do zero. Os jogos e os torneios ficam no registo.": "从零开始。对局和锦标赛会保留在记录中。",
  "Para confirmar, escreve {w}:": "请输入 {w} 以确认：",
