  "O formato ao acaso escolhe entre os que têm decks do meta. Commander a 4 joga em mesas. Fora do casual entra sempre pelo menos 20% do meta, para os torneios serem ranked. A seguir é só vê-los no Registo e no Ao vivo: o simulador reparte os jogos como está nas Definições.": "随机赛制从有环境套牌的赛制中选择。四人 Commander 以牌桌进行。非休闲时至少 20% 为环境套牌，使锦标赛计入排位。之后在记录和直播中观看即可：模拟器按设置分配对局。",
