  "Tens {c} moedas. O histórico e as estatísticas das apostas ficam; só a carteira volta ao começo (e conta como um recomeço).": "你有 {c} 枚硬币。下注记录和统计会保留；只有钱包恢复初始（并记为一次重置）。",
  "Escolhe os dados acima e carrega em «Lançar». Depois podes agarrar um dado com o rato ou o dedo e atirá-lo outra vez.": "在上方选择骰子并点击「投掷」。之后可以用鼠标或手指抓起骰子再掷一次。",
  "Vista dos dados": "骰子视图",
  "a rolar…": "滚动中…",
  "d4 a d100 e moeda em 3D: lança-se, agarra-se e atira-se com o dedo, com registo.": "3D 的 d4 到 d100 和硬币：投掷、抓起并用手指抛出，附记录。",
  "d100 = dois d10: dezenas e unidades": "d100 = 两个 d10：十位与个位",
  "Escolhe os dados acima e carrega em «Lançar». Depois podes agarrar um dado com o rato ou o dedo e atirá-lo outra vez. O d100 são dois d10: dezenas (00–90) e unidades.": "在上方选择骰子并点击「投掷」。之后可以用鼠标或手指抓起骰子再掷一次。d100 是两个 d10：十位（00–90）和个位。",
  "Contadores de {n}": "{n} 的计数器",
  "Veneno, comandante e mais": "毒性、指挥官等",
  "🎲 ao acaso (onde tenho decks)": "🎲 随机（我有套牌的赛制）",
  "🎲 ao acaso (todos os formatos)": "🎲 随机（所有赛制）",
  "O formato ao acaso escolhe entre os que têm decks do meta (por omissão, só onde também tens decks teus). Commander a 4 joga em mesas. Fora do casual entra sempre pelo menos 20% do meta, para os torneios serem ranked. A seguir é só vê-los no Registo e no Ao vivo: o simulador reparte os jogos como está nas Definições.": "随机赛制从有环境套牌的赛制中选择（默认只选你也有自己套牌的赛制）。四人 Commander 以牌桌进行。非休闲时至少 20% 为环境套牌，使锦标赛计入排位。之后在记录和直播中观看即可：模拟器按设置分配对局。",
  "Ouro: 1.º lugar": "金：第 1 名",
  "Prata: 2.º lugar": "银：第 2 名",
  "Bronze: 3.º lugar": "铜：第 3 名",
  "aceitar decks legais de outros formatos": "接受其他赛制中在此合法的套牌",
  "Aceitar decks legais de outros formatos ({l})": "接受其他赛制的合法套牌（{l}）",
  "clica para jogares com este": "点击以使用此套牌",
  "Com o meta ligado entra pelo menos 20% (torneio ranked). Desligado dá um torneio interno, não ranked.": "开启环境套牌时至少占 20%（排位锦标赛）。关闭则为内部、不计排位的锦标赛。",
  "«{d}» tem cartas que não são legais em {f}.": "「{d}」含有在 {f} 中不合法的卡牌。",
  "escolher…": "自选…",
  "Fora do casual o meta fica com pelo menos 20% (ranked).": "非休闲时环境套牌至少占 20%（排位）。",
  "jogas com este (clica para tirar)": "你使用此套牌（点击取消）",
  "Os decks têm de ser legais carta a carta neste formato (o servidor confirma).": "套牌必须在此赛制中逐张合法（服务器会检查）。",
  "Pediste {n} decks, mas para {t} em {f} só há {k} com estas regras.": "你要求 {n} 套牌，但 {f} 的{t}按这些规则只有 {k} 套。",
  "Sem meta: torneios internos, não ranked.": "无环境套牌：内部、不计排位的锦标赛。",
  "Só em Legacy, Vintage, Modern e Pioneer; cada deck tem de ser legal carta a carta.": "仅限 Legacy、Vintage、Modern 和 Pioneer；每套牌须逐张合法。",
  "Os meus decks (não os da comunidade) ficam com contorno azul nas chaves, classificações, jogos e pódios.": "我的套牌（非社区）在对阵表、排名、对局和领奖台中显示蓝色轮廓。",
  "Destacar os meus decks em todos os torneios": "在所有锦标赛中突出显示我的套牌",
  "Junta os 2.ºs e 3.ºs lugares dos torneios anteriores (com o mesmo filtro dos campeões). Troféus normais, mas valem menos pontos.": "汇集以往锦标赛的第 2、3 名（与冠军相同的筛选）。普通奖杯，但分数较低。",
  "Liga dos pódios ✓": "领奖台联赛 ✓",
  "Liga dos pódios": "领奖台联赛",
  "Só há {k} 2.ºs e 3.ºs lugares de torneios anteriores para isto (mínimo {m}).": "以往锦标赛只有 {k} 个第 2、3 名可用（至少 {m}）。",
  "a ler… {p}%": "识别中… {p}%",
  "Aponta a câmara a uma carta e ela entra no deck aberto.": "用相机对准卡牌，它会加入当前打开的套牌。",
