  "Ler carta": "扫描卡牌",
  "Ler uma carta pela câmara ou por uma foto": "用相机或照片扫描卡牌",
  "Não consegui ler o nome. Tenta com mais luz, a carta direita e o nome bem visível.": "无法识别名称。请增加光线、摆正卡牌并让名称清晰可见。",
  "O leitor não arrancou: {e}": "识别器未能启动：{e}",
  "Põe a carta dentro da moldura, com o nome em cima, e carrega em «Ler».": "将卡牌放入框内，名称朝上，然后点击「扫描」。",
  "Tira uma foto à carta (de frente, com o nome visível) ou escolhe uma imagem. Para a câmara ao vivo abre a app em https.": "为卡牌拍照（正面、名称可见）或选择图片。如需实时相机，请通过 https 打开应用。",
