  "O formato ao acaso escolhe entre os que têm decks do meta. Commander a 4 joga em mesas. A seguir é só vê-los no Registo e no Ao vivo: o simulador reparte os jogos como está nas Definições.": "随机赛制从有环境套牌的赛制中选择。四人 Commander 以牌桌进行。之后在记录和直播中观看即可：模拟器按设置分配对局。",
  "🎲 onde tenho decks": "🎲 我有套牌的",
  "Pediste {w} decks; entraram {n} (o máximo para {t} com os decks que há).": "你要求 {w} 套牌；实际加入 {n} 套（{t}在现有套牌下的上限）。",
  "percentagens ao acaso em cada torneio": "每个锦标赛随机比例",
  "Que decks entram": "哪些套牌参加",
