  "capa: {c}": "封面：{c}",
  "🧙 Meu": "🧙 我的",
  "Ainda não convidaste ninguém.": "你还没有邀请任何人。",
  "Cada amigo recebe um link pessoal. Ao abri-lo fica convidado neste Grimório: os decks dele ficam aqui marcados com o nome, entra nos teus torneios e arenas e aposta com a sua carteira. Não vê nem mexe em mais nada, e podes revogar o link quando quiseres.": "每位好友都会获得专属链接。打开后即成为此 Grimório 的访客：其套牌以其名字保存在这里，可参加你的锦标赛和竞技场，并用自己的钱包下注。看不到也改不了其他内容，你可随时撤销链接。",
