  "O link deixa de entrar. Os decks dele ficam na tua Biblioteca, marcados com o nome.": "链接将失效。其套牌以其名字保留在你的套牌库中。",
  "Para convidar pela internet é preciso um endereço público (o Grimório num servidor com domínio, ou a partilha pela internet que vem a seguir). Em casa basta o link da rede local ou o QR.": "通过互联网邀请需要公网地址（带域名的服务器上的 Grimório，或即将推出的互联网共享）。在家使用局域网链接或二维码即可。",
