  "Abre uma sala no «✦ Criar» (opção «Abrir como sala para amigos»): os convidados entram com um deck seu e tu começas.": "在「✦ 创建」中开房（选项「作为好友房间打开」）：访客带自己的套牌加入，由你开始。",
