  "{n} cartas usam o cemitério: hate de cemitério (Rest in Peace, Leyline of the Void…) corta o plano.": "{n} 张牌使用坟墓场：针对坟墓场的牌（Rest in Peace、Leyline of the Void…）会打断计划。",
  "{n} criaturas, {e} com evasão (voar, atropelar, imbloqueáveis…).": "{n} 个生物，{e} 个有闪避（飞行、践踏、不可阻挡…）。",
