  "Toca para ler": "点按识别",
  "Põe a carta dentro da moldura, com o nome em cima, e toca na imagem ou em «Tirar foto e ler».": "将卡牌放入框内，名称在上方，然后点按画面或“拍照并识别”。",
  "Cartas no deck principal (com o comandante). O mínimo é o do formato.": "主牌中的卡牌数（含指挥官）。最小值由赛制决定。",
  "O recomendado vem da fórmula de Frank Karsten: custo médio do deck e ramp/compra baratos.": "建议值来自 Frank Karsten 公式：套牌平均费用与低费加速/抽牌。",
  "Média do valor de mana (MV) das cartas que não são terrenos. Abaixo de 2,5 é um deck rápido.": "非地牌的平均法术力值（MV）。低于 2.5 为快攻套牌。",
  "Probabilidade de a mão inicial de 7 cartas ter 2 a 4 terrenos (conta exata, hipergeométrica).": "7 张起手中有 2 至 4 张地的概率（超几何分布精确计算）。",
  "Soma dos preços da Cardmarket (via Scryfall), com as edições que escolheste.": "Cardmarket 价格之和（经 Scryfall），按你选择的版本计算。",
  "Problemas com as regras do formato: cartas ilegais, cópias a mais, tamanho. Clica para ver as melhorias.": "违反赛制规则的问题：不合法卡牌、副本过多、张数。点击查看改进。",
  "Quantas cartas há de cada custo de mana, criaturas em baixo e o resto em cima. Passa o rato numa barra para ver os números.": "每个法术力费用的牌数，生物在下、其余在上。悬停柱子查看数字。",
  "À esquerda, as cores dos símbolos de mana nos custos; à direita, as cores que os terrenos produzem. Devem ser parecidas: uma cor que pede muito mais do que recebe falha nos primeiros turnos.": "左边是费用中法术力符号的颜色，右边是地产出的颜色。两者应相近：需求远大于供给的颜色会在前几回合卡手。",
  "Contas exatas com os terrenos do deck: a mão de 7 cartas e os terrenos que vês até ao 3.º e 4.º turno, a jogar primeiro.": "按套牌地数精确计算：7 张起手，以及先手到第 3、4 回合能看到的地。",
  "Vias de vitória e riscos tirados da construção do deck e dos jogos de teste; o sideboard é avaliado contra o que te venceu.": "从套牌构筑和测试牌局得出的获胜方式与风险；备牌按击败你的牌来评估。",
  "Fontes de cada cor que o deck tem e de que precisa nesta fase (Frank Karsten); a vermelho as que faltam.": "套牌现有与此阶段所需的各色来源（Frank Karsten）；缺少的显示为红色。",
  "Os eixos do deck: cartas que geram algo (fichas, marcadores, cemitério…) e cartas que o aproveitam.": "套牌的主轴：产生资源的牌（衍生物、指示物、坟墓场…）与利用它的牌。",
  "Quantas cartas fazem cada coisa (remoção, compra, ramp…) contra o recomendado para o formato; a linha marca o alvo.": "每种功能（移除、抽牌、加速…）的牌数与赛制建议的对比；竖线为目标。",
  "Todos os jogos deste deck no Laboratório, torneios e Arena, sem contar o mesmo jogo duas vezes.": "此套牌在实验室、锦标赛和竞技场的所有牌局，同一局不重复计算。",
  "O que mais vale a pena mudar primeiro: legalidade, terrenos e cores, funções em falta e trocas por cartas melhores.": "最值得优先修改的：合法性、地与颜色、缺少的功能，以及换成更好的牌。",
