  "Abre uma sala em «✦ Nova sala» e partilha o link: quem o abre entra com um deck seu e tu começas quando estiverem todos.": "在「✦ 新房间」中开一个房间并分享链接：打开链接的人带着自己的套牌加入，人到齐后由你开始。",
