  "As partidas do teu deck esperam por ti e jogas tu, na mesa do Grimório; as outras jogam-nas os bots.": "你的套牌的对局会等你，在 Grimório 牌桌上由你来打；其余对局由机器人进行。",
  "Atenção: {l} com menos de 10 jogos — a diferença pode ser sorte.": "注意：{l} 少于 10 局——差距可能只是运气。",
