  "chega mais vezes ao objetivo do deck ({a} contra {b})": "更常达成套牌的目标（{a} 对 {b}）",
  "Cria um torneio em que jogas tu os jogos do teu deck, na mesa do Grimório; os outros jogam-nos os bots": "创建一个锦标赛：你的套牌的对局由你在 Grimório 牌桌上亲自打，其余由机器人进行",
  "De quem": "所属",
  "Desligado: todos os decks são do formato escolhido, só que o torneio não conta para os ratings.": "关闭：所有套牌都来自所选赛制，但锦标赛不计入评分。",
  "é mais alto (custo médio {a} contra {b}): as cartas mais caras pesam mais quando chegam": "更高（平均费用 {a} 对 {b}）：更贵的卡一旦出场更有分量",
  "é mais baixo (custo médio {a} contra {b}): joga mais cedo e tropeça menos": "更低（平均费用 {a} 对 {b}）：更早出牌，更少卡手",
  "Entre jogos podes trocar cartas entre o deck e o sideboard. As trocas valem até ao fim da série.": "每局之间可以在套牌和备牌之间换卡。更换在整个系列赛中有效。",
  "Escolhe «o meu deck» na lista (fora do Commander, das mesas e das equipas).": "在列表中选择「我的套牌」（Commander、多人桌和团队赛除外）。",
