  "Na mão: um clique levanta a carta e mostra-a; para a jogar, arrasta-a para a mesa (ou duplo clique). Se a largares de volta na mão, fica no sítio onde a largaste.": "手牌中：单击会抬起并展示这张牌；要打出，就把它拖到牌桌上（或双击）。放回手牌时，它会留在你放下的位置。",
