  "Tecla para virar a carta debaixo do rato (a outra face, ou de pernas para o ar; só no teu ecrã)": "翻转鼠标下那张牌的按键（另一面，或上下颠倒；只在你的屏幕上）",
  "Tecla para virar (tap) a carta tua na mesa debaixo do rato — o mesmo que clicar nela": "横置鼠标下你牌桌上那张牌的按键——与单击它相同",
  "tem menos interação ({a} contra {b}) e mesmo assim ganha mais: a força vem de outro lado": "互动更少（{a} 对 {b}）却赢得更多：它的强项在别处",
