  "Quem joga: os bots do Forge (eliminação, suíço, liga, grupos…). Os amigos veem e apostam.": "谁来玩：Forge 机器人（淘汰赛、瑞士轮、联赛、小组赛…）。好友观战并下注。",
  "Quem joga: só vocês, 2 a 4 amigos, sem bots. Cada um mexe nas suas cartas, como numa mesa a sério.": "谁来玩：只有你们 2 到 4 位好友，没有机器人。每人操作自己的牌，就像在真实牌桌上。",
  "Registo da mesa": "牌桌记录",
  "Regras: nenhuma automática. Qualquer formato, Commander incluído.": "规则：无自动规则。任何赛制，包括指挥官。",
  "Regras: todas, aplicadas pelo Forge.": "规则：全部，由 Forge 执行。",
  "revelar a mão": "展示手牌",
  "👁 Revelar a todos": "👁 向所有人展示",
  "sair da mesa": "离开牌桌",
  "Sem bots: cada um mexe nas suas cartas. Ninguém valida as jogadas.": "没有机器人：每人操作自己的牌。没有人校验出牌。",
  "Sem bots e sem regras automáticas: cada um mexe nas suas cartas.": "没有机器人也没有自动规则：每人操作自己的牌。",
  "Sem bots e sem regras automáticas: o servidor só guarda a mesa e esconde as mãos e as bibliotecas. Num deck de Commander, o comandante fica na zona de comando e a vida começa em 40.": "没有机器人也没有自动规则：服务器只保存牌桌，并隐藏手牌和牌库。指挥官套牌中，指挥官放在指挥区，起始生命为 40。",
  "sem bots, sem regras": "无机器人，无规则",
  "Só tu vês: depois escolhe o que fica no topo, vai para o fundo, para a mão ou para o cemitério": "只有你能看到：然后选择哪些留在顶部、放到底部、进手牌或进坟墓场",
  "só tu vês estas cartas (a primeira é a de cima)": "只有你能看到这些牌（第一张在最上面）",
  "Terminar": "结束",
  "terminar a mesa": "结束牌桌",
  "Terminar a mesa para todos?": "为所有人结束牌桌？",
