  "Já jogaste um terreno neste turno.": "你本回合已经使用过地了。",
  "Não é instantâneo: só na tua fase principal, com a pilha vazia.": "这不是瞬间：只能在你的主阶段且堆叠为空时施放。",
  "Falta mana: custa {n} e tens {m} por usar (terrenos por virar e reserva).": "法术力不足：需要 {n}，你只有 {m}（未横置的地和法术力池）。",
  "Talvez não haja um alvo válido para ela agora (ou falte a cor certa de mana).": "现在可能没有合法目标（或缺少正确颜色的法术力）。",
  "O Forge não a deixa jogar agora: falta a cor certa de mana ou uma condição da carta.": "Forge 现在不允许使用：缺少正确颜色的法术力或卡牌条件。",
