  "Ainda não está pronto": "尚未准备",
  "Ainda não tens decks neste Grimório. Senta-te com um deck que te emprestem, com um deck do meta, ou cola a tua lista (ou um link) e fica guardado para a próxima.": "你在这个 Grimório 里还没有套牌。可以用别人借给你的套牌或环境套牌入座，或粘贴你的牌表（或链接），它会保存下来供下次使用。",
  "A ler o deck…": "正在读取套牌…",
  "A lista tem só {n} cartas reconhecidas. Cola uma lista com «4 Lightning Bolt» por linha (ou um link do Moxfield, Archidekt…).": "该牌表只识别出 {n} 张牌。请粘贴每行一条“4 Lightning Bolt”格式的牌表（或 Moxfield、Archidekt… 链接）。",
