  "Passar a vez de {p}": "结束 {p} 的回合",
  "{P} começa o turno: desvira tudo e compra {n}": "{P} 开始回合：重置所有永久物并抓 {n} 张牌",
  "Precisa de pelo menos {m} jogadores (há {n})": "至少需要 {m} 名玩家（当前 {n} 名）",
  "Precisa de pelo menos {m} jogadores: partilha o link (em cima). Enquanto esperas, podes testar o teu deck sozinho:": "至少需要 {m} 名玩家：分享链接（见上方）。等待期间，你可以单独测试你的套牌：",
  "{P} recomeça o jogo com o mesmo deck": "{P} 用同一套牌重新开始游戏",
