  "{p} saiu de «{r}»": "{p} 离开了“{r}”",
  "🤝 {p} sentou-se em «{r}» com {d}": "🤝 {p} 带着 {d} 坐进了“{r}”",
  "Quem joga: só tu, para testar um deck (goldfish). Sem sala nem link.": "玩家：只有你，用于测试套牌（goldfish）。无需房间或链接。",
  "Reagir": "回应",
  "Recomeçar com o mesmo deck?": "用同一套牌重新开始？",
  "Regras: nenhuma automática. Novo turno, recomeçar e a vida de um adversário imaginário.": "规则：不自动执行。提供新回合、重新开始和假想对手的生命值。",
  "Revelar a mão": "展示手牌",
  "Sair da mesa": "离开牌桌",
  "Sair deste lugar": "离开此座位",
  "Sem bots e sem regras automáticas: o servidor só guarda a mesa e esconde as mãos e as bibliotecas. Num deck de Commander, o comandante fica na zona de comando e a vida começa em 40. Na sala podes emprestar decks a quem não tiver.": "没有机器人，也不自动执行规则：服务器只保存牌桌并隐藏手牌和牌库。使用指挥官套牌时，指挥官位于指挥区，生命从 40 开始。在房间里你可以把套牌借给没有套牌的人。",
  "Sem decks do meta neste formato.": "此赛制没有环境套牌。",
  "🪑 Sentar-me com este deck": "🪑 用此套牌入座",
