  "Só um deck": "仅一副套牌",
  "Terminar a mesa": "结束牌桌",
  "Terminar esta mesa?": "结束此牌桌？",
  "testa um deck teu na mesa livre: compras, jogas, viras e contas o dano a um adversário imaginário, sem ninguém à espera": "在自由牌桌上测试你的套牌：抓牌、出牌、横置，并计算对假想对手造成的伤害，无需等待他人",
  "Todas as cartas voltam à biblioteca, baralhas e compras 7; a vida e o turno recomeçam.": "所有牌回到牌库，洗牌后抓 7 张；生命和回合重置。",
  "Todos prontos.": "全员已准备。",
  "Todos prontos! A mesa abre em {s} s…": "全员已准备！牌桌将在 {s} 秒后开启…",
  "Traz a tua biblioteca: o link do teu perfil (Archidekt, Moxfield…) ou vários links de decks. Ficam guardados como decks teus e depois escolhes com qual te sentas.": "带上你的套牌库：你的个人主页链接（Archidekt、Moxfield…）或多个套牌链接。它们会保存为你的套牌，之后再选择用哪一副入座。",
  "📚 Trazer vários decks": "📚 导入多副套牌",
  "tu": "你",
  "um amigo mandou-te o link da sala dele: entras como o teu perfil, com os teus decks": "朋友发来了他的房间链接：你将以自己的个人资料和套牌加入",
  "Vão o nome do teu perfil e as listas dos decks (nada mais). Da próxima vez és reconhecido e os decks atualizam-se.": "只会发送你的个人资料名称和套牌列表（仅此而已）。下次你会被识别，套牌也会自动更新。",
  "Abrir a mesa já": "立即开启牌桌",
  "Cada partida joga-se numa mesa livre entre os donos dos decks. Quando os dois carregam em «Pronto», a mesa abre. Desistir = perder; o resultado também se pode combinar na mesa ou ser marcado por quem aloja.": "每场对局都在套牌主人之间的自由牌桌上进行。双方都按下“准备”后，牌桌开启。认输 = 判负；结果也可在牌桌上商定，或由主持人标记。",
  "🤝 Empate": "🤝 平局",
  "Ganhei este jogo": "我赢了这局",
  "🏆 Ganhou {p}": "🏆 {p} 获胜",
  "Ganhou {p}": "{p} 获胜",
  "Ir para a mesa": "前往牌桌",
  "jogo {g} · melhor de {bo} ({a}–{b})": "第 {g} 局 · {bo} 局制 ({a}–{b})",
  "jogo único": "单局",
  "Marcar o jogo:": "标记本局：",
  "Não concordo": "我不同意",
  "Nenhuma partida à espera agora.": "目前没有等待中的对局。",
  "Novo torneio de mesa livre": "新建自由牌桌锦标赛",
  "Os dois decks são teus: abre a mesa e joga os dois lados (troca de lugar na mesa), ou marca o resultado.": "两副套牌都是你的：开启牌桌并操控双方（在牌桌上换座），或直接标记结果。",
  "Os dois decks são teus: joga agora o outro lado": "两副套牌都是你的：现在操控另一方",
  "Partidas à mesa livre": "自由牌桌对局",
  "{P} não concorda com o resultado": "{P} 不同意该结果",
  "{P} propõe: empate": "{P} 提议：平局",
  "{P} propõe: ganhou {T}": "{P} 提议：{T} 获胜",
  "✓ Pronto (à espera do outro)": "✓ 已准备（等待对方）",
  "Proposta: empate": "提议：平局",
  "Proposta: ganhou {p}": "提议：{p} 获胜",
  "Quem joga: vocês, sem bots, cada um com um ou vários decks seus. Cada partida abre uma mesa livre entre os dois.": "参赛者：你们自己，没有机器人，每人使用一副或多副自己的套牌。每场对局在两人之间开启一张自由牌桌。",
  "Regras: nenhuma automática; desistir = perder, o resultado combina-se na mesa ou marca-o quem aloja. Conta como torneio de amigos.": "规则：无自动规则；认输 = 判负，结果在牌桌上商定或由主持人标记。计为好友锦标赛。",
  "Resultado: empate": "结果：平局",
  "Resultado: ganhou {T} 🏆": "结果：{T} 获胜 🏆",
  "sem bots: junta os teus decks aqui (podes pôr vários) e partilha o link; cada amigo entra com um ou vários decks seus. Cada partida joga-se numa mesa livre entre os donos dos decks.": "没有机器人：在这里加入你的套牌（可加入多副）并分享链接；每位好友带一副或多副自己的套牌加入。每场对局都在套牌主人之间的自由牌桌上进行。",
  "Tens {n} deck(s) neste torneio. Podes juntar mais.": "你在本锦标赛中有 {n} 副套牌。可以再加入更多。",
